SELECT AVG(fare) AS average_fare
FROM rides
WHERE status = 'completed';

SELECT AVG(fare) AS avg_fare_amount
FROM rides
WHERE status = 'completed' AND surge_multiplier > 1;

SELECT SUM(amount) AS total_completed_payment_amount
FROM payments
WHERE payment_status = 'completed';

SELECT make, COUNT(*) AS vehicle_count
FROM vehicles
GROUP BY make;

SELECT COUNT(*) AS cancelled_rides_count
FROM rides
WHERE status = 'cancelled';

SELECT
  ROUND(100.0 * COUNT(*) FILTER (WHERE payment_status = 'failed') / COUNT(*), 2) AS failed_payment_percentage
FROM payments;

SELECT
  ROUND(
    100.0 * COUNT(*) FILTER (WHERE payment_status = 'refunded') / COUNT(*),
    2
  ) AS refunded_percentage
FROM payments;

SELECT COUNT(*) AS driver_count
FROM users
WHERE user_type = 'driver';

SELECT COUNT(*) AS active_drivers
FROM users
WHERE user_type = 'driver' AND is_active = TRUE;

SELECT COUNT(*) AS ride_requests_2026
FROM rides
WHERE EXTRACT(YEAR FROM requested_at) = 2026;
